/**
 * The cue registry: every sound the game makes, by id, as a synth recipe built from oscillators,
 * noise and envelopes at runtime (sfxr-style, no audio files and nothing generated by AI), with
 * its throttle. A licensed sound pack replaces a cue later by naming a file for it
 * (AudioEngineOptions.files, or `file` here): the engine plays the decoded file once it has
 * loaded, and the recipe until then or when the file fails to load.
 */

import type { FilterKind, Waveform } from './context';

export const CUE_IDS = [
  'lob',
  'explosion',
  'hit',
  'crit',
  'kill',
  'killBig',
  'ignite',
  'freeze',
  'shatter',
  'playerHit',
  'waveCleared',
  'runEnd',
  'uiClick',
  'buy',
] as const;

export type CueId = (typeof CUE_IDS)[number];

/** One voice of a recipe: a waveform or noise, through an optional filter, under an envelope. */
export interface SynthLayer {
  readonly wave: Waveform | 'noise';
  /** Start frequency in Hz; for noise, the playback rate of the noise buffer (1 = as made). */
  readonly freq: number;
  /** Frequency at the end of the envelope (an exponential sweep); the start one when omitted. */
  readonly freqEnd?: number;
  /** Seconds after the cue starts. */
  readonly delay?: number;
  /** Seconds to the peak, then seconds of exponential decay to silence. */
  readonly attack: number;
  readonly decay: number;
  /** Peak gain of this layer, before the cue's volume. */
  readonly gain: number;
  readonly filter?: {
    readonly type: FilterKind;
    readonly freq: number;
    readonly freqEnd?: number;
    readonly q?: number;
  };
}

export interface CueDef {
  readonly layers: readonly SynthLayer[];
  /** The cue's gain under the master volume. */
  readonly volume: number;
  /** A play this soon after the cue's last one is dropped. */
  readonly cooldownMs: number;
  /** Voices of this cue that may sound at once; more are dropped. */
  readonly maxVoices: number;
  /** Random pitch spread, as a fraction (0.05 = up to 5% up or down). */
  readonly pitchJitter: number;
  /** High-priority cues are not held back by the engine's overall voice cap. */
  readonly priority: 'normal' | 'high';
  /** A licensed file that replaces the recipe (a URL the page can fetch). */
  readonly file?: string;
}

